/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    —
 * depends    —
 * used by    —
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../..')
const soPath = path.join(root, 'extraction-core/dumps/v29.0.0-arm64/libil2cpp.so')
const dumpPath = path.join(root, 'extraction-core/dumps/v29.0.0-arm64/dump.cs')
const outPath = path.join(root, 'packages/platform/src/game-data/v29.0/wave-spawn-disasm.json')

/** @param {Buffer} data */
function loadElfSegments(data) {
  if (data.subarray(0, 4).toString() !== '\u007fELF') throw new Error('not ELF')
  const ePhoff = Number(data.readBigUInt64LE(0x20))
  const ePhentsize = data.readUInt16LE(0x36)
  const ePhnum = data.readUInt16LE(0x38)
  /** @type {[number, number, number][]} */
  const segments = []
  for (let i = 0; i < ePhnum; i += 1) {
    const base = ePhoff + i * ePhentsize
    if (data.readUInt32LE(base) !== 1) continue
    const pOffset = Number(data.readBigUInt64LE(base + 8))
    const pVaddr = Number(data.readBigUInt64LE(base + 16))
    const pFilesz = Number(data.readBigUInt64LE(base + 32))
    segments.push([pVaddr, pFilesz, pOffset])
  }
  if (!segments.length) throw new Error('no PT_LOAD segments')
  return segments
}

/** @param {[number, number, number][]} segments */
function rvaToOffset(segments, rva) {
  for (const [vaddr, filesz, offset] of segments) {
    if (rva >= vaddr && rva < vaddr + filesz) return offset + (rva - vaddr)
  }
  throw new Error(`RVA ${rva.toString(16)} not mapped`)
}

/** @param {string} text */
function buildRvaIndex(text) {
  /** @type {Map<number, string>} */
  const index = new Map()
  const re = /\/\/ RVA: (0x[0-9A-Fa-f]+)[^\n]*\n[^\n]*?\b(\w+)\([^)]*\)\s*\{/g
  for (const m of text.matchAll(re)) {
    index.set(parseInt(m[1], 16), m[2])
  }
  return index
}

/**
 * @param {Buffer} data
 * @param {[number, number, number][]} segments
 */
function scanBlCalls(data, startRva, endRva, segments) {
  /** @type {{ at: number, target: number, kind: 'bl' | 'b' }[]} */
  const hits = []
  for (let pc = startRva & ~3; pc + 4 <= endRva; pc += 4) {
    const off = rvaToOffset(segments, pc)
    const w = data.readUInt32LE(off)
    const top = w >> 26
    if (top !== 0b100101 && top !== 0b000101) continue
    let imm = w & 0x3ffffff
    if (imm & (1 << 25)) imm -= 1 << 26
    hits.push({ at: pc, target: pc + (imm << 2), kind: top === 0b100101 ? 'bl' : 'b' })
  }
  return hits
}

/** @param {Buffer} data @param {[number, number, number][]} segments */
function scanInstructionCounts(data, startRva, endRva, segments) {
  const counts = { bl: 0, blr: 0, br: 0, b: 0, ret: 0, adrp: 0 }
  for (let pc = startRva & ~3; pc + 4 <= endRva; pc += 4) {
    const w = data.readUInt32LE(rvaToOffset(segments, pc))
    if ((w >> 26) === 0b100101) counts.bl += 1
    else if ((w >> 26) === 0b000101) counts.b += 1
    else if ((w & 0xffff0000) === 0xd63f0000) counts.blr += 1
    else if ((w & 0xffff0000) === 0xd61f0000) counts.br += 1
    else if (w === 0xd65f_03c0) counts.ret += 1
    else if ((w & 0x9f000000) === 0x90000000) counts.adrp += 1
  }
  return counts
}

/** @param {Map<number, string>} index */
function resolveRva(index, rva) {
  return index.get(rva) ?? `0x${rva.toString(16)}`
}

/** @param {Map<number, string>} index */
function findMethodStart(index, atRva) {
  let best = 0
  for (const start of index.keys()) {
    if (start <= atRva && start > best) best = start
  }
  return best
}

const WAVE_UPDATE = { start: 0x01_fcc87c, end: 0x01_fcd064 }
const SPAWN_RANDOM_BASIC = 0x01_fdb514
const SPAWN_ENEMY = 0x01_fdb800
const GET_WAVE_BASE_HEALTH = { start: 0x01_fd9888, end: 0x01_fda020 }

const data = fs.readFileSync(soPath)
const segments = loadElfSegments(data)
const dumpText = fs.readFileSync(dumpPath, 'utf8')
const rvaIndex = buildRvaIndex(dumpText)

const insnCounts = scanInstructionCounts(data, WAVE_UPDATE.start, WAVE_UPDATE.end, segments)
const sanityGetWaveBaseHealth = scanInstructionCounts(
  data,
  GET_WAVE_BASE_HEALTH.start,
  GET_WAVE_BASE_HEALTH.end,
  segments,
)
const blCalls = scanBlCalls(data, WAVE_UPDATE.start, WAVE_UPDATE.end, segments)
const spawnCalls = blCalls.filter((c) => c.target === SPAWN_RANDOM_BASIC)

/** Global xrefs — IL2CPP often uses BL from many sites; filter to WaveUpdate body. */
const codeSeg = segments.find(([vaddr, filesz]) => WAVE_UPDATE.start >= vaddr && WAVE_UPDATE.start < vaddr + filesz)
const globalSpawnBasic = codeSeg
  ? scanBlCalls(data, codeSeg[0], codeSeg[0] + codeSeg[1], segments).filter((c) => c.target === SPAWN_RANDOM_BASIC)
  : []
const globalSpawnEnemy = codeSeg
  ? scanBlCalls(data, codeSeg[0], codeSeg[0] + codeSeg[1], segments).filter((c) => c.target === SPAWN_ENEMY)
  : []
const spawnCallsInWaveUpdate = globalSpawnBasic.filter(
  (c) => c.at >= WAVE_UPDATE.start && c.at < WAVE_UPDATE.end,
)
const spawnEnemyCallsInWaveUpdate = globalSpawnEnemy.filter(
  (c) => c.at >= WAVE_UPDATE.start && c.at < WAVE_UPDATE.end,
)

const callSummary = blCalls.map((c) => ({
  at: `0x${c.at.toString(16)}`,
  target: `0x${c.target.toString(16)}`,
  kind: c.kind,
  method: resolveRva(rvaIndex, c.target),
}))

const uniqueTargets = [...new Set(blCalls.map((c) => c.target))].map((target) => ({
  target: `0x${target.toString(16)}`,
  method: resolveRva(rvaIndex, target),
  count: blCalls.filter((c) => c.target === target).length,
}))

const payload = {
  source: 'v29.0.0-arm64 libil2cpp.so BL scan (ELF-mapped RVAs)',
  rvas: {
    WaveUpdate: { start: `0x${WAVE_UPDATE.start.toString(16)}`, end: `0x${WAVE_UPDATE.end.toString(16)}` },
    SpawnRandomBasicEnemy: `0x${SPAWN_RANDOM_BASIC.toString(16)}`,
  },
  elfSegments: segments.map(([vaddr, filesz, offset]) => ({
    vaddr: `0x${vaddr.toString(16)}`,
    filesz: `0x${filesz.toString(16)}`,
    offset: `0x${offset.toString(16)}`,
    delta: `0x${(vaddr - offset).toString(16)}`,
  })),
  spawnRandomBasicEnemyCallCount: spawnCallsInWaveUpdate.length || spawnCalls.length,
  spawnRandomBasicEnemyCallSitesInWaveUpdate: (spawnCallsInWaveUpdate.length ? spawnCallsInWaveUpdate : spawnCalls).map(
    (c) => `0x${c.at.toString(16)}`,
  ),
  spawnRandomBasicEnemyGlobalCallCount: globalSpawnBasic.length,
  spawnRandomBasicEnemyGlobalCallSites: globalSpawnBasic.map((c) => ({
    at: `0x${c.at.toString(16)}`,
    kind: c.kind,
    inWaveUpdate: c.at >= WAVE_UPDATE.start && c.at < WAVE_UPDATE.end,
    caller: resolveRva(rvaIndex, findMethodStart(rvaIndex, c.at)),
  })),
  spawnEnemyGlobalCallCount: globalSpawnEnemy.length,
  spawnEnemyCallsInWaveUpdate: spawnEnemyCallsInWaveUpdate.map((c) => ({
    at: `0x${c.at.toString(16)}`,
    kind: c.kind,
    caller: resolveRva(rvaIndex, findMethodStart(rvaIndex, c.at)),
  })),
  waveUpdateInstructionCounts: insnCounts,
  sanityGetWaveBaseHealthInstructionCounts: sanityGetWaveBaseHealth,
  waveUpdateBlCallCount: blCalls.length,
  waveUpdateBlTargets: uniqueTargets.sort((a, b) => b.count - a.count),
  waveUpdateBlCalls: callSummary,
  simulatorModel: {
    expectedEnemiesPerTickFormula: 'callSites * spawnGatePassRate + enemyDoubleSpawnChance',
    calibratedEnemiesPerTickFallback: 3.25,
    defaultRandomBasicCallSites: spawnCallsInWaveUpdate.length || spawnCalls.length || 3,
  },
}

fs.mkdirSync(path.dirname(outPath), { recursive: true })
fs.writeFileSync(outPath, `${JSON.stringify(payload, null, 2)}\n`)
console.log(JSON.stringify({
  spawnRandomBasicEnemyCallCount: payload.spawnRandomBasicEnemyCallCount,
  sites: payload.spawnRandomBasicEnemyCallSitesInWaveUpdate,
  waveUpdateBlCallCount: payload.waveUpdateBlCallCount,
}, null, 2))
